package net.officefloor.hq.app.paste;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Corrections;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.claim.ValidClaim;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Adds a DRAFT claim per pasted line, in order, to the person it names (compared as names are).
 *  Every line is first checked as {@link net.officefloor.hq.app.claim.AddClaim} checks a claim (its
 *  person on the sheet, not retired before its date, its due-by outside a closed period, its reference
 *  used by no claim on the sheet nor an earlier line), so a refused line adds nothing; then each is
 *  added, logged and recorded as CLAIM_ADDED. */
public class PasteClaims {
    private record Pending(Person person, ValidClaim claim, LocalDate date, LocalDate dueBy, String corrects) {
    }

    public void paste(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val PasteLines lines,
            PersonRepository people, SheetRepository sheets, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, ClaimLogRepository log, Audit audit,
            HolidayRepository holidays,
            Out<PasteResult> result) throws PeriodClosedException, InvalidClaimException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        List<Pending> pending = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PasteLine line : lines.lines()) {
            Person person = people.findByName(id, line.name());
            if (person == null) {
                throw new InvalidClaimException("Not on the sheet: " + line.name());
            }
            ValidClaim request = line.claim();
            LocalDate date = request.date() != null ? request.date() : settings.entryDate(id);
            if (person.retiredBefore(date)) {
                throw new InvalidClaimException("The person is retired from " + person.getRetiredFrom());
            }
            // The due-by is fixed now, by the terms of the grade in force on its date, as they stood on its date,
            // counted in business days past the weekends and the sheet's holidays as they are now.
            LocalDate dueBy = holidays.dueBy(id, date, settings.terms(id, person, date.toString()));
            periods.requireOpen(id, dueBy.toString());
            String corrects = Corrections.check(request, id, person.getId(), claims);
            // A reference is used once on the sheet: also once within the paste.
            claims.requireRefFree(id, request.ref(), 0);
            if (request.ref() != null && !refs.add(request.ref().toLowerCase(Locale.ROOT))) {
                throw new InvalidClaimException("The reference is repeated in the paste: " + request.ref());
            }
            pending.add(new Pending(person, request, date, dueBy, corrects));
        }
        for (Pending p : pending) {
            Claim claim = claims.add(id, p.person().getId(), p.claim().amount(), p.date(),
                    p.claim().note(), p.corrects(), p.dueBy(), user, p.claim().ref());
            if (periods.softClosedOn(id, claim.getDueBy())) claims.markLateEntry(claim);
            log.record(claim, user);
            audit.record("CLAIM_ADDED sheet=" + id + " by=" + user + " person=" + p.person().getName()
                    + " amount=" + claim.getAmount() + " date=" + claim.getDate() + claim.getAuditRef());
            if (claim.isLateEntry()) {
                audit.record("LATE_ENTRY sheet=" + id + " by=" + user + " person=" + p.person().getName()
                        + " amount=" + claim.getAmount() + " date=" + claim.getDate());
            }
        }
        result.set(new PasteResult(pending.size()));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimsKey, pasteClaims } from './api';

/** A box that adds a DRAFT claim per pasted line of name,amount,date,note, and how many it added.
 *  The count is cleared while it runs; a refused paste adds nothing and shows an error. */
export function PasteClaims({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const submitOnce = useSubmitOnce();

  const paste = useMutation({
    mutationFn: (input: string) => pasteClaims(sheetId, user, input),
    // Not awaited: the count shows as soon as the paste is done, never after its new rows.
    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }); },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const input = text;
        submitOnce(() => {
          paste.reset();
          return paste.mutateAsync(input);
        });
      }}
    >
      <label>
        Paste claims (name,amount,date,note per line; end the note with " #ref" to give a reference){' '}
        <textarea data-testid="paste-claims" rows={3} value={text}
          onChange={(e) => {
            setText(e.target.value);
            if (paste.isError) paste.reset();
          }} />
      </label>{' '}
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add pasted claims
      </button>
      {paste.isSuccess && (
        <>
          {' '}Added <span data-testid="paste-added">{paste.data.added}</span>
        </>
      )}
      {paste.isError && (
        <span data-testid="paste-error">Every line needs a name on the sheet and an amount of 0.00 or more with up to two decimals, dated on or before the person's retirement and outside a closed period: nothing was added.</span>
      )}
    </form>
  );
}
